solutionCode:
export function substituirTrecho(lista, inicio, quantidade, ...novos) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  const copia = lista.slice();
  copia.splice(inicio, quantidade, ...novos);
  return copia;
}
